200	// migrateCheckpointsV2 returns the /full/<n> refs migration wrote so callers
201	// can pass them as exclusions to the generation-metadata repair pass.
202	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, []plumbing.ReferenceName, error) {
203		v1List, err := v1Store.ListCommitted(ctx)
204		if err != nil {
205			return nil, nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
206		}
207	
208		if len(v1List) == 0 {
209			return &migrateResult{}, nil, nil
210		}
211	
212		sortMigratableCheckpoints(v1List)
213		total := len(v1List)
214		result := &migrateResult{total: total}
215		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
216		defer progress.Finish()
217	
218		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
219		fullCurrentExistsBefore := fullCurrentRefErr == nil
220	
221		// One up-front tree walk to make per-session "are /full/* artifacts
222		// present?" checks O(1) inside the migration loop.
223		fullArtifactsIndex, err := v2Store.BuildFullSessionArtifactsIndex()
224		if err != nil {
225			return nil, nil, fmt.Errorf("build v2 /full/* presence index: %w", err)
226		}
227	
228		batchSize := migrateFullBatchSize()
229		pendingFull := make([]migratedFullCheckpoint, 0, batchSize)
230		var writtenRefs []plumbing.ReferenceName
231		nextGeneration := 0
232	
233		for _, info := range v1List {
234			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force, fullArtifactsIndex)
235			result.missingSessions += outcome.missingSessions
236			if outcome.compactTranscriptSkipped {
237				result.compactTranscriptSkipped++
238			}
239	
240			if migrateErr != nil {
241				switch {
242				case errors.Is(migrateErr, errAlreadyMigrated):
243					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
244					result.skipped++
245				case errors.Is(migrateErr, errNoMigratableSessions):
246					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
247					result.skipped++
248				default:
249					logging.Error(ctx, "checkpoint migration failed",
250						slog.String("checkpoint_id", string(info.CheckpointID)),
251						slog.String("error", migrateErr.Error()),
252					)
253					result.failed++
254				}
255				progress.Increment()
256				continue
257			}
258	
259			if fullCheckpoint != nil {
260				pendingFull = append(pendingFull, *fullCheckpoint)
261				if len(pendingFull) == batchSize {
262					if nextGeneration == 0 {
263						// Resolve the archive slot only when the first full batch is ready;
264						// force migration may prune existing archived refs earlier in the loop.
265						next, nextErr := v2Store.NextGenerationNumber()
266						if nextErr != nil {
267							return result, writtenRefs, fmt.Errorf("list archived v2 generations: %w", nextErr)
268						}
269						nextGeneration = next
270					}
271					refName := checkpoint.ArchivedGenerationRefName(nextGeneration)
272					if packErr := writeMigratedFullGeneration(ctx, repo, refName, pendingFull); packErr != nil {
273						return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
274					}
275					writtenRefs = append(writtenRefs, refName)
276					nextGeneration++
277					pendingFull = make([]migratedFullCheckpoint, 0, batchSize)
278				}
279			}
280			result.migrated++
281			progress.Increment()
282		}
283	
284		progress.Finish()
285		stopFinalize := startSpinner(progressOut, "Packing migrated raw transcripts")
286		if len(pendingFull) > 0 {
287			if err := writeMigratedFinalFullCurrent(ctx, repo, v2Store, pendingFull); err != nil {
288				stopFinalize(false)
289				return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
290			}
291			// If /full/current already had checkpoints, this final migration write can
292			// briefly push the generation past the threshold before rotation. That
293			// mirrors other v2 ref-merge cases where a generation may exceed the soft
294			// threshold by a small amount.
295			if refName, rotated, err := v2Store.RotateCurrentGenerationIfNeeded(ctx, batchSize); err != nil {
296				stopFinalize(false)
297				return result, writtenRefs, fmt.Errorf("failed to rotate migrated full/current generation: %w", err)
298			} else if rotated {
299				writtenRefs = append(writtenRefs, refName)
300			}
301		} else if len(writtenRefs) > 0 && !fullCurrentExistsBefore {
302			if err := ensureEmptyV2FullCurrent(ctx, repo); err != nil {
303				stopFinalize(false)
304				return result, writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
305			}
306		}
307		stopFinalize(true)
308	
309		return result, writtenRefs, nil
310	}
