320	// sortMigratableCheckpoints sorts oldest-first so archived generations
321	// preserve chronological order. Zero timestamps sort last; CheckpointID
322	// breaks ties for deterministic reruns.
323	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
324		sort.SliceStable(checkpoints, func(i, j int) bool {
325			left := checkpoints[i].CreatedAt
326			right := checkpoints[j].CreatedAt
327			switch {
328			case left.IsZero() && right.IsZero():
329				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
330			case left.IsZero():
331				return false
332			case right.IsZero():
333				return true
334			case left.Equal(right):
335				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
336			default:
337				return left.Before(right)
338			}
339		})
340	}
