347	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
348		var outcome migrateCheckpointOutcome
349	
350		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
351		if err != nil {
352			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
353		}
354	
355		if existing != nil && !force {
356			// Already in v2. Pack sessions whose /full/* artifacts are missing
357			// (resume an interrupted run) and backfill transcript.jsonl on /main
358			// where it's missing. With nothing to do on either front, return
359			// errAlreadyMigrated so the caller counts it as skipped.
360			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
361			if err != nil && !errors.Is(err, errAlreadyMigrated) {
362				return nil, outcome, err
363			}
364			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
365			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
366				outcome.compactTranscriptSkipped = true
367			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
368				return nil, outcome, backfillErr
369			}
370			if fullCheckpoint == nil {
371				if backfilled > 0 {
372					return nil, outcome, nil
373				}
374				return nil, outcome, errAlreadyMigrated
375			}
376			return fullCheckpoint, outcome, nil
377		}
378	
379		if existing != nil && force {
380			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
381				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
382			}
383		}
384	
385		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
386		if err != nil {
387			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
388		}
389		if summary == nil {
390			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
391		}
392	
393		compactFailed := false
394		shouldCopyTaskMetadata := false
395		skippedMissingSessions := 0
396		migratedSessions := 0
397		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
398		fullCheckpoint := &migratedFullCheckpoint{
399			checkpointID: info.CheckpointID,
400		}
401	
402		for sessionIdx := range len(summary.Sessions) {
403			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
404			if skipped {
405				skippedMissingSessions++
406				outcome.missingSessions++
407				continue
408			}
409			if readErr != nil {
410				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
411			}
412			if content.Metadata.IsTask {
413				shouldCopyTaskMetadata = true
414			}
415	
416			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
417	
418			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
419			if compacted != nil {
420				opts.CompactTranscript = compacted
421				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
422			} else if len(content.Transcript) > 0 {
423				compactFailed = true
424			}
425	
426			mainOpts := opts
427			mainOpts.Transcript = redact.AlreadyRedacted(nil)
428			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
429			if writeErr != nil {
430				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
431			}
432			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
433			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
434				sessionIndex: v2SessionIdx,
435				content:      content,
436			})
437			migratedSessions++
438		}
439	
440		if migratedSessions == 0 {
441			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
442		}
443	
444		if shouldCopyTaskMetadata {
445			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
446			if taskErr != nil {
447				logging.Warn(ctx, "failed to copy task metadata to v2",
448					slog.String("checkpoint_id", string(info.CheckpointID)),
449					slog.String("error", taskErr.Error()),
450				)
451			} else {
452				fullCheckpoint.taskTrees = taskTrees
453			}
454		}
455	
456		if compactFailed {
457			outcome.compactTranscriptSkipped = true
458			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
459				slog.String("checkpoint_id", string(info.CheckpointID)),
460				slog.Int("migrated_sessions", migratedSessions),
461			)
462		}
463		if skippedMissingSessions > 0 {
464			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
465				slog.String("checkpoint_id", string(info.CheckpointID)),
466				slog.Int("missing_sessions", skippedMissingSessions),
467			)
468		}
469	
470		return fullCheckpoint, outcome, nil
471	}
