581	func (s *V2GitStore) resetFullCurrentRefIfUnchanged(ctx context.Context, refName plumbing.ReferenceName, expectedRef *plumbing.Reference, newHash plumbing.Hash) (bool, error) {
582		newRef := plumbing.NewHashReference(refName, newHash)
583		if err := s.repo.Storer.CheckAndSetReference(newRef, expectedRef); err != nil {
584			if errors.Is(err, storage.ErrReferenceHasChanged) {
585				logging.Info(ctx, "rotation: /full/current changed before reset, leaving current ref intact")
586				return false, nil
587			}
588			return false, fmt.Errorf("rotation: failed to reset /full/current: %w", err)
589		}
590		return true, nil
591	}
