```go
//go:build unix

package lockfile

import (
	"errors"
	"os"

	"golang.org/x/sys/unix"
)

// tryLockExclusive returns ErrLocked on contention (EWOULDBLOCK), nil on
// success, other errors on I/O failures.
func tryLockExclusive(f *os.File) error {
	err := unix.Flock(int(f.Fd()), unix.LOCK_EX|unix.LOCK_NB)
	if err == nil {
		return nil
	}
	if errors.Is(err, unix.EWOULDBLOCK) {
		return ErrLocked
	}
	return err
}

func unlock(f *os.File) error {
	return unix.Flock(int(f.Fd()), unix.LOCK_UN)
}
```

- [ ] **Step 6: Implement the Windows shim `lockfile_windows.go`**

Create `cmd/entire/cli/lockfile/lockfile_windows.go`:

```go
//go:build windows

package lockfile

import (
	"errors"
	"os"

	"golang.org/x/sys/windows"
)

// tryLockExclusive returns ErrLocked on contention
// (ERROR_LOCK_VIOLATION), nil on success, other errors on I/O failures.
// LOCKFILE_FAIL_IMMEDIATELY makes the call non-blocking, matching the
// LOCK_NB semantics used on Unix.
func tryLockExclusive(f *os.File) error {
	handle := windows.Handle(f.Fd())
	var ol windows.Overlapped
	err := windows.LockFileEx(
		handle,
		windows.LOCKFILE_EXCLUSIVE_LOCK|windows.LOCKFILE_FAIL_IMMEDIATELY,
		0,
		^uint32(0), ^uint32(0), // lock the entire file (max DWORD low/high)
		&ol,
	)
	if err == nil {
		return nil
	}
	if errors.Is(err, windows.ERROR_LOCK_VIOLATION) {
		return ErrLocked
	}
	return err
}

func unlock(f *os.File) error {
	handle := windows.Handle(f.Fd())
	var ol windows.Overlapped
	return windows.UnlockFileEx(handle, 0, ^uint32(0), ^uint32(0), &ol)
}
```

If `windows.LOCKFILE_EXCLUSIVE_LOCK` or `windows.LOCKFILE_FAIL_IMMEDIATELY` are not exported in the version of `golang.org/x/sys` we use, fall back to the literal values `0x00000002` and `0x00000001`. Verify with `grep -n LOCKFILE_EXCLUSIVE_LOCK ~/go/pkg/mod/golang.org/x/sys*/windows/*.go`.

