1	// Package lockfile provides a tiny cross-platform file-lock primitive
2	// built on OS advisory locks (flock on Unix, LockFileEx on Windows).
3	// The lock is auto-released by the kernel when the holding process
4	// exits, so there is no stale-lock recovery problem.
5	package lockfile
6	
7	import (
8		"errors"
9		"fmt"
10		"os"
11		"strconv"
12		"strings"
13	)
14	
15	// ErrLocked is returned by Acquire when another process holds the lock.
16	var ErrLocked = errors.New("lockfile already held")
17	
18	// Lock represents an acquired exclusive lock on a path. Release exactly
19	// once when done; the OS will also release on process exit.
20	type Lock struct {
21		f *os.File
22	}
23	
24	// Acquire opens path with O_CREATE|O_RDWR mode 0600, attempts a
25	// non-blocking exclusive OS-level lock, and on success writes the
26	// current PID into the file (advisory diagnostic only). Returns
27	// ErrLocked if another process holds the lock; non-ErrLocked errors
28	// indicate I/O or permission failures and should be reported with
29	// context. The Go runtime sets FD_CLOEXEC on os.OpenFile, so the FD is
30	// not inherited by subprocesses.
31	func Acquire(path string) (*Lock, error) {
32		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
33		if err != nil {
34			return nil, fmt.Errorf("open lock file %s: %w", path, err)
35		}
36		if err := tryLockExclusive(f); err != nil {
37			_ = f.Close()
38			return nil, err
39		}
40		if err := writePID(f); err != nil {
41			_ = unlock(f)
42			_ = f.Close()
43			return nil, fmt.Errorf("write PID to lock file %s: %w", path, err)
44		}
45		return &Lock{f: f}, nil
46	}
47	
48	// Release releases the OS lock and closes the underlying file handle.
49	// Safe to call exactly once; subsequent calls are no-ops.
50	func (l *Lock) Release() error {
51		if l == nil || l.f == nil {
52			return nil
53		}
54		f := l.f
55		l.f = nil
56		unlockErr := unlock(f)
57		closeErr := f.Close()
58		if unlockErr != nil {
59			return unlockErr
60		}
61		return closeErr
62	}
